// Generated by Claude Code
package ui;

import grading.session.RunOutcome;
import javafx.scene.control.Label;
import javafx.scene.layout.HBox;

/** The status pill at the top right: one line of text, coloured by how the work is going. */
final class StatusPill {

    /** The pill's colour: none, blue while working, amber when something needs checking, green when done. */
    enum Tone {
        NONE(null), WORKING("working"), ATTENTION("attention"), DONE("done");

        private final String styleClass;

        Tone(String styleClass) {
            this.styleClass = styleClass;
        }
    }

    private final HBox badge;
    private final Label text;
    private Tone tone = Tone.NONE;
    private String savedText = "";
    private Tone savedTone = Tone.NONE;

    StatusPill(HBox badge, Label text) {
        this.badge = badge;
        this.text = text;
    }

    /** Changes the text and keeps the colour. */
    void show(String message) {
        text.setText(message);
    }

    /** Changes the text and the colour. */
    void show(String message, Tone newTone) {
        text.setText(message);
        tone = newTone;
        for (Tone each : Tone.values()) {
            badge.getStyleClass().remove(each.styleClass);
        }
        if (newTone.styleClass != null) {
            badge.getStyleClass().add(newTone.styleClass);
        }
    }

    /** Says how a grading run ended, amber when students need review. */
    void showRunEnd(RunOutcome outcome, long toReview) {
        switch (outcome) {
            case CANCELLED -> show("Grading cancelled", Tone.NONE);
            case FAILED -> show("Grading failed", Tone.ATTENTION);
            case COMPLETED, NONE -> show(toReview == 0 ? "Grading complete"
                    : "Grading complete — " + toReview + " need review", toReview == 0 ? Tone.DONE : Tone.ATTENTION);
        }
    }

    /** Remembers what the pill says now, before an import that may be rejected. */
    void save() {
        savedText = text.getText();
        savedTone = tone;
    }

    /** Shows what was saved again: a rejected folder changed nothing, so the earlier status still holds. */
    void restore() {
        show(savedText, savedTone);
    }
}
